def encode(s):
    if not s:
        return ''

    parts = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            parts.append(current)
            if count > 1:
                parts.append(str(count))
            current = ch
            count = 1

    parts.append(current)
    if count > 1:
        parts.append(str(count))

    return ''.join(parts)


def decode(s):
    result = []
    i = 0

    while i < len(s):
        ch = s[i]
        i += 1

        start = i
        while i < len(s) and s[i].isdigit():
            i += 1

        if i > start:
            count = int(s[start:i])
        else:
            count = 1

        result.append(ch * count)

    return ''.join(result)
